export async function fetchUser(id, { retries = 3 } = {}) {
  for (let attempt = 0; attempt < retries; attempt++) {
    try {
      const res = await fetch(`https://api.example.com/users/${id}?try=${attempt + 1}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return await res.json();
    } catch (err) {
      console.warn('attempt failed:', err instanceof Error ? err.message : err);
    } finally {
      utils.log?.('done');
    }
  }
  return null;
}
